"""Verify the RECOMMENDATIONS section structure in the unpacked document.xml."""

try:
    from defusedxml import minidom
except ImportError:
    from xml.dom import minidom

XML_PATH = "unpacked/word/document.xml"
dom = minidom.parse(XML_PATH)
body = dom.getElementsByTagName("w:body")[0]


def element_text(elem):
    parts = []
    for node in elem.childNodes:
        if node.nodeType == node.TEXT_NODE:
            if node.data.strip():
                parts.append(node.data)
        elif node.nodeType == node.ELEMENT_NODE:
            parts.append(element_text(node))
    return "".join(parts)


paras = body.getElementsByTagName("w:p")
print(f"Total paragraphs in body: {len(paras)}")
print("--- Last 9 paragraphs (text repr) ---")
for p in paras[-9:]:
    print(repr(element_text(p)))
print("--- sectPr position check ---")
sect = body.getElementsByTagName("w:sectPr")
print(f"sectPr count: {len(sect)}")
print(f"Last element of body is sectPr: {body.lastChild is sect[0] or body.lastChild.previousSibling is sect[0]}")

